CREATE TABLE IF NOT EXISTS decision_heads (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, owner_id TEXT NOT NULL, question TEXT NOT NULL, revision INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, idempotency_key TEXT NOT NULL, UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS decision_revisions (decision_id TEXT NOT NULL, tenant_id TEXT NOT NULL, revision INTEGER NOT NULL, data_json TEXT NOT NULL, PRIMARY KEY(decision_id,revision));
CREATE TABLE IF NOT EXISTS decision_runs (id TEXT PRIMARY KEY, decision_id TEXT NOT NULL, tenant_id TEXT NOT NULL, data_json TEXT NOT NULL, policy_json TEXT NOT NULL, idempotency_key TEXT NOT NULL, UNIQUE(tenant_id,decision_id,idempotency_key));
CREATE TABLE IF NOT EXISTS decision_attempts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, tenant_id TEXT NOT NULL, provider TEXT NOT NULL, round INTEGER NOT NULL, attempt INTEGER NOT NULL, started_at TEXT NOT NULL, result_json TEXT, UNIQUE(run_id,provider,round,attempt));
CREATE TABLE IF NOT EXISTS decision_reports (id TEXT PRIMARY KEY, decision_id TEXT NOT NULL, tenant_id TEXT NOT NULL, run_id TEXT NOT NULL UNIQUE, data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decision_checks (id TEXT PRIMARY KEY, decision_id TEXT NOT NULL, tenant_id TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decision_reviews (id TEXT PRIMARY KEY, decision_id TEXT NOT NULL, tenant_id TEXT NOT NULL, report_hash TEXT NOT NULL, reviewer_id TEXT NOT NULL, data_json TEXT NOT NULL, UNIQUE(tenant_id,decision_id,report_hash,reviewer_id));
CREATE TABLE IF NOT EXISTS decision_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, decision_id TEXT NOT NULL, tenant_id TEXT NOT NULL, event TEXT NOT NULL, actor_id TEXT NOT NULL, created_at TEXT NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decision_budgets (tenant_id TEXT PRIMARY KEY, calls_reserved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS decision_outbox (run_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, available_at INTEGER NOT NULL, lease_token TEXT, lease_until INTEGER);
CREATE INDEX IF NOT EXISTS decision_heads_tenant ON decision_heads(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS decision_outbox_ready ON decision_outbox(available_at,lease_until);
CREATE INDEX IF NOT EXISTS decision_audit_scope ON decision_audit(tenant_id,decision_id,id);
CREATE TRIGGER IF NOT EXISTS decision_revisions_no_update BEFORE UPDATE ON decision_revisions BEGIN SELECT RAISE(ABORT,'Decision revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS decision_revisions_no_delete BEFORE DELETE ON decision_revisions BEGIN SELECT RAISE(ABORT,'Decision revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS decision_reports_no_update BEFORE UPDATE ON decision_reports BEGIN SELECT RAISE(ABORT,'Decision reports are immutable'); END;
CREATE TRIGGER IF NOT EXISTS decision_reports_no_delete BEFORE DELETE ON decision_reports BEGIN SELECT RAISE(ABORT,'Decision reports are immutable'); END;
CREATE TRIGGER IF NOT EXISTS decision_checks_no_update BEFORE UPDATE ON decision_checks BEGIN SELECT RAISE(ABORT,'Evidence checks are append-only'); END;
CREATE TRIGGER IF NOT EXISTS decision_checks_no_delete BEFORE DELETE ON decision_checks BEGIN SELECT RAISE(ABORT,'Evidence checks are append-only'); END;
CREATE TRIGGER IF NOT EXISTS decision_reviews_no_update BEFORE UPDATE ON decision_reviews BEGIN SELECT RAISE(ABORT,'Decision reviews are append-only'); END;
CREATE TRIGGER IF NOT EXISTS decision_reviews_no_delete BEFORE DELETE ON decision_reviews BEGIN SELECT RAISE(ABORT,'Decision reviews are append-only'); END;
CREATE TRIGGER IF NOT EXISTS decision_audit_no_update BEFORE UPDATE ON decision_audit BEGIN SELECT RAISE(ABORT,'Decision audit is append-only'); END;
CREATE TRIGGER IF NOT EXISTS decision_audit_no_delete BEFORE DELETE ON decision_audit BEGIN SELECT RAISE(ABORT,'Decision audit is append-only'); END;
CREATE TRIGGER IF NOT EXISTS decision_attempt_result_immutable BEFORE UPDATE ON decision_attempts WHEN OLD.result_json IS NOT NULL BEGIN SELECT RAISE(ABORT,'Completed attempts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS decision_attempts_no_delete BEFORE DELETE ON decision_attempts BEGIN SELECT RAISE(ABORT,'Decision attempts are append-only'); END;
